    },
    {
      "node_code": "N_9d81b3e8e9fd2223",
      "definition": "研究机场飞行区道面（跑道、滑行道、机坪）的结构设计、材料选择及性能评价，包括结构层组合、厚度计算及耐久性分析，确保满足航空器荷载要求。",
      "boundary": "本节点聚焦于道面结构本身的力学设计与材料性能，如刚性/柔性道面结构层组合、厚度计算、接缝设计。边界在于区分“结构设计”与“布局规划”，具体的平面位置、几何尺寸归入“机场场址与飞行区土建布局”，具体的施工方法归入施工节点。不包含飞机设计或航空管制。",
      "includes": [
        "跑道、滑行道、机坪的结构层组合设计与厚度计算",
        "道面材料（水泥混凝土、沥青混合料）的性能要求与选择",
        "道面接缝设计、传力杆布置及耐久性、疲劳寿命分析"
      ],
      "excludes": [
        "道面的平面布局、几何尺寸及与周边设施的相对位置",
        "道面施工的具体工艺流程、设备操作及现场质量控制"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_8ca555a60eb1f5ce",
          "rule": "本节点关注“怎么建”（结构层与材料）；父节点关注“在哪里建”和“怎么布局”（几何与规划）。"
        },
        {
          "other_code": "N_fb01fcd06dc8682f",
          "rule": "本节点关注“道面结构”（上部结构）；兄弟节点关注“地基”（下部土体）的处理与稳定。"
        }
      ],
      "cross_boundary_rule": "当结构设计受地基条件影响时，地基参数作为输入归入地基节点，道面结构响应归入本节点。"
    }
  ]
}
